abstract class Component { public abstract long Size(); }
sealed class File : Component { public long Bytes; public override long Size() => Bytes; }
sealed class Dir : Component {
    private readonly List<Component> _children = new();
    public void Add(Component c) => _children.Add(c);
    public override long Size() { long s = 0; foreach (var c in _children) s += c.Size(); return s; }
}
